819: static int64_t FileSize(const char* path) {
820:   FILE* f = fopen(path, "rb");
821:   int64_t retval;
822:   if (f == NULL) {
823:     return -1;
824:   }
825:   if (fseek(f, 0L, SEEK_END) != 0) {
826:     fclose(f);
827:     return -1;
828:   }
829:   retval = ftell(f);
830:   if (fclose(f) != 0) {
831:     return -1;
832:   }
833:   return retval;
834: }
