836: static int CopyTimeStat(const struct stat* statbuf, const char* output_path,
837:                         FILE* fout) {
838: #if HAVE_UTIMENSAT
839:   struct timespec times[2];
840:   int fd = fileno(fout);
841:   (void)output_path;
842:   if (fd < 0) return -1;
843:   times[0].tv_sec = statbuf->st_atime;
844:   times[0].tv_nsec = ATIME_NSEC(statbuf);
845:   times[1].tv_sec = statbuf->st_mtime;
846:   times[1].tv_nsec = MTIME_NSEC(statbuf);
847:   return futimens(fd, times);
848: #else
849:   struct utimbuf times;
850:   (void)fout;
851:   times.actime = statbuf->st_atime;
852:   times.modtime = statbuf->st_mtime;
853:   return utime(output_path, &times);
854: #endif
855: }
