857: /* Copy file times and permissions.
858:    TODO(eustas): this is a "best effort" implementation; honest cross-platform
859:    fully featured implementation is way too hacky; add more hacks by request. */
860: static void CopyStat(const char* input_path, const char* output_path,
861:                      FILE* fout) {
862:   struct stat statbuf;
863:   int fd;
864:   int res;
865:   if (input_path == 0 || output_path == 0 || fout == NULL) {
866:     return;
867:   }
868:   fd = fileno(fout);
869:   if (fd < 0) {
870:     return;
871:   }
872:   if (stat(input_path, &statbuf) != 0) {
873:     return;
874:   }
875:   /* Flush any stdio-buffered output before setting timestamps; otherwise the
876:      buffered write() that fclose() issues would clobber the atime/mtime we
877:      just set. */
878:   if (fflush(fout) != 0) {
879:     return;
880:   }
881:   res = CopyTimeStat(&statbuf, output_path, fout);
882:   res = fchmod(fd, statbuf.st_mode & (S_IRWXU | S_IRWXG | S_IRWXO));
883:   if (res != 0) {
884:     fprintf(stderr, "setting access bits failed for [%s]: %s\n",
885:             PrintablePath(output_path), strerror(errno));
886:   }
887:   res = fchown(fd, (uid_t)-1, statbuf.st_gid);
888:   if (res != 0) {
889:     fprintf(stderr, "setting group failed for [%s]: %s\n",
890:             PrintablePath(output_path), strerror(errno));
891:   }
892:   res = fchown(fd, statbuf.st_uid, (gid_t)-1);
893:   if (res != 0) {
894:     fprintf(stderr, "setting user failed for [%s]: %s\n",
895:             PrintablePath(output_path), strerror(errno));
896:   }
897: }
