900:    |*dictionary_size| is set to resulting buffer size. */
901: static BROTLI_BOOL ReadDictionary(Context* context, Command command) {
902:   static const int kMaxDictionarySize =
903:       BROTLI_MAX_DISTANCE - BROTLI_MAX_BACKWARD_LIMIT(24);
904:   FILE* f;
905:   int64_t file_size_64;
906:   uint8_t* buffer;
907:   size_t bytes_read;
908: 
909:   if (context->dictionary_path == NULL) return BROTLI_TRUE;
910:   f = fopen(context->dictionary_path, "rb");
911:   if (f == NULL) {
912:     fprintf(stderr, "failed to open dictionary file [%s]: %s\n",
913:             PrintablePath(context->dictionary_path), strerror(errno));
914:     return BROTLI_FALSE;
915:   }
916: 
917:   file_size_64 = FileSize(context->dictionary_path);
918:   if (file_size_64 == -1) {
919:     fprintf(stderr, "could not get size of dictionary file [%s]",
920:             PrintablePath(context->dictionary_path));
921:     fclose(f);
922:     return BROTLI_FALSE;
923:   }
924: 
925:   if (file_size_64 > kMaxDictionarySize) {
926:     fprintf(stderr, "dictionary [%s] is larger than maximum allowed: %d\n",
927:             PrintablePath(context->dictionary_path), kMaxDictionarySize);
928:     fclose(f);
929:     return BROTLI_FALSE;
930:   }
931:   context->dictionary_size = (size_t)file_size_64;
932: 
933:   buffer = (uint8_t*)malloc(context->dictionary_size);
934:   if (!buffer) {
935:     fprintf(stderr, "could not read dictionary: out of memory\n");
936:     fclose(f);
937:     return BROTLI_FALSE;
938:   }
939:   bytes_read = fread(buffer, sizeof(uint8_t), context->dictionary_size, f);
940:   if (bytes_read != context->dictionary_size) {
941:     free(buffer);
942:     fprintf(stderr, "failed to read dictionary [%s]: %s\n",
943:             PrintablePath(context->dictionary_path), strerror(errno));
944:     fclose(f);
945:     return BROTLI_FALSE;
946:   }
947:   fclose(f);
948:   context->dictionary = buffer;
949:   if (command == COMMAND_COMPRESS) {
950:     context->prepared_dictionary = BrotliEncoderPrepareDictionary(
951:         BROTLI_SHARED_DICTIONARY_RAW, context->dictionary_size,
952:         context->dictionary, BROTLI_MAX_QUALITY, NULL, NULL, NULL);
953:     if (context->prepared_dictionary == NULL) {
954:       fprintf(stderr, "failed to prepare dictionary [%s]\n",
955:               PrintablePath(context->dictionary_path));
956:       return BROTLI_FALSE;
957:     }
958:   }
959:   return BROTLI_TRUE;
960: }
