962: static BROTLI_BOOL NextFile(Context* context) {
963:   const char* arg;
964:   size_t arg_len;
965: 
966:   /* Iterator points to last used arg; increment to search for the next one. */
967:   context->iterator++;
968: 
969:   context->input_file_length = -1;
970: 
971:   /* No input path; read from console. */
972:   if (context->input_count == 0) {
973:     if (context->iterator > 1) return BROTLI_FALSE;
974:     context->current_input_path = NULL;
975:     /* Either write to the specified path, or to console. */
976:     context->current_output_path = context->output_path;
977:     return BROTLI_TRUE;
978:   }
979: 
980:   /* Skip option arguments. */
981:   while (context->iterator == context->not_input_indices[context->ignore]) {
982:     context->iterator++;
983:     context->ignore++;
984:   }
985: 
986:   /* All args are scanned already. */
987:   if (context->iterator >= context->argc) return BROTLI_FALSE;
988: 
989:   /* Iterator now points to the input file name. */
990:   arg = context->argv[context->iterator];
991:   arg_len = strlen(arg);
992:   /* Read from console. */
993:   if (arg_len == 1 && arg[0] == '-') {
994:     context->current_input_path = NULL;
995:     context->current_output_path = context->output_path;
996:     return BROTLI_TRUE;
997:   }
998: 
999:   context->current_input_path = arg;
1000:   context->input_file_length = FileSize(arg);
1001:   context->current_output_path = context->output_path;
1002: 
1003:   if (context->output_path) return BROTLI_TRUE;
1004:   if (context->write_to_stdout) return BROTLI_TRUE;
1005: 
1006:   strcpy(context->modified_path, arg);
1007:   context->current_output_path = context->modified_path;
1008:   /* If output is not specified, input path suffix should match. */
1009:   if (context->decompress) {
1010:     size_t suffix_len = strlen(context->suffix);
1011:     char* name = (char*)FileName(context->modified_path);
1012:     char* name_suffix;
1013:     size_t name_len = strlen(name);
1014:     if (name_len < suffix_len + 1) {
1015:       fprintf(stderr, "empty output file name for [%s] input file\n",
1016:               PrintablePath(arg));
1017:       context->iterator_error = BROTLI_TRUE;
1018:       return BROTLI_FALSE;
1019:     }
1020:     name_suffix = name + name_len - suffix_len;
1021:     if (strcmp(context->suffix, name_suffix) != 0) {
1022:       fprintf(stderr, "input file [%s] suffix mismatch\n",
1023:               PrintablePath(arg));
1024:       context->iterator_error = BROTLI_TRUE;
1025:       return BROTLI_FALSE;
1026:     }
1027:     name_suffix[0] = 0;
1028:     return BROTLI_TRUE;
1029:   } else {
1030:     strcpy(context->modified_path + arg_len, context->suffix);
1031:     return BROTLI_TRUE;
1032:   }
1033: }
