1035: static BROTLI_BOOL OpenFiles(Context* context) {
1036:   BROTLI_BOOL is_ok = OpenInputFile(context->current_input_path, &context->fin);
1037:   if (!context->test_integrity && is_ok) {
1038:     is_ok = OpenOutputFile(
1039:         context->current_output_path, &context->fout, context->force_overwrite);
1040:   }
1041:   return is_ok;
1042: }
