1044: static BROTLI_BOOL CloseFiles(Context* context, BROTLI_BOOL rm_input,
1045:                               BROTLI_BOOL rm_output) {
1046:   BROTLI_BOOL is_ok = BROTLI_TRUE;
1047:   if (!context->test_integrity && context->fout) {
1048:     /* Apply metadata via the still-open fd, before close, to close the TOCTOU
1049:        window between fclose() and the metadata syscalls. */
1050:     if (!rm_output && context->copy_stat && context->current_output_path) {
1051:       CopyStat(context->current_input_path, context->current_output_path,
1052:                context->fout);
1053:     }
1054:     if (fclose(context->fout) != 0) {
1055:       if (is_ok) {
1056:         fprintf(stderr, "fclose failed [%s]: %s\n",
1057:                 PrintablePath(context->current_output_path), strerror(errno));
1058:       }
1059:       is_ok = BROTLI_FALSE;
1060:     }
1061:     if (rm_output && context->current_output_path) {
1062:       unlink(context->current_output_path);
1063:     }
1064:   }
1065: 
1066:   if (context->fin) {
1067:     if (fclose(context->fin) != 0) {
1068:       if (is_ok) {
1069:         fprintf(stderr, "fclose failed [%s]: %s\n",
1070:                 PrintablePath(context->current_input_path), strerror(errno));
1071:       }
1072:       is_ok = BROTLI_FALSE;
1073:     }
1074:   }
1075:   if (rm_input && context->current_input_path) {
1076:     unlink(context->current_input_path);
1077:   }
1078: 
1079:   context->fin = NULL;
1080:   context->fout = NULL;
1081: 
1082:   return is_ok;
1083: }
