1085: static const size_t kFileBufferSize = 1 << 19;
1086: 
1087: static void InitializeBuffers(Context* context) {
1088:   context->available_in = 0;
1089:   context->next_in = NULL;
1090:   context->available_out = kFileBufferSize;
1091:   context->next_out = context->output;
1092:   context->total_in = 0;
1093:   context->total_out = 0;
1094:   if (context->verbosity > 0) {
1095:     context->start_time = clock();
1096:   }
1097: }
1098: 
1099: /* This method might give the false-negative result.
1100:    However, after an empty / incomplete read it should tell the truth. */
1101: static BROTLI_BOOL HasMoreInput(Context* context) {
1102:   return feof(context->fin) ? BROTLI_FALSE : BROTLI_TRUE;
1103: }
1104: 
1105: static BROTLI_BOOL ProvideInput(Context* context) {
1106:   context->available_in =
1107:       fread(context->input, 1, kFileBufferSize, context->fin);
1108:   context->total_in += context->available_in;
1109:   context->next_in = context->input;
1110:   if (ferror(context->fin)) {
1111:     fprintf(stderr, "failed to read input [%s]: %s\n",
1112:             PrintablePath(context->current_input_path), strerror(errno));
1113:     return BROTLI_FALSE;
1114:   }
1115:   return BROTLI_TRUE;
1116: }
1117: 
1118: /* Internal: should be used only in Provide-/Flush-Output. */
1119: static BROTLI_BOOL WriteOutput(Context* context) {
1120:   size_t out_size = (size_t)(context->next_out - context->output);
1121:   context->total_out += out_size;
1122:   if (out_size == 0) return BROTLI_TRUE;
1123:   if (context->test_integrity) return BROTLI_TRUE;
1124: 
1125:   fwrite(context->output, 1, out_size, context->fout);
1126:   if (ferror(context->fout)) {
1127:     fprintf(stderr, "failed to write output [%s]: %s\n",
1128:             PrintablePath(context->current_output_path), strerror(errno));
1129:     return BROTLI_FALSE;
1130:   }
1131:   return BROTLI_TRUE;
1132: }
1133: 
1134: static BROTLI_BOOL ProvideOutput(Context* context) {
1135:   if (!WriteOutput(context)) return BROTLI_FALSE;
1136:   context->available_out = kFileBufferSize;
1137:   context->next_out = context->output;
1138:   return BROTLI_TRUE;
1139: }
1140: 
1141: static BROTLI_BOOL FlushOutput(Context* context) {
1142:   if (!WriteOutput(context)) return BROTLI_FALSE;
1143:   context->available_out = 0;
1144:   context->next_out = context->output;
1145:   return BROTLI_TRUE;
1146: }
