1148: static void PrintBytes(size_t value) {
1149:   if (value < 1024) {
1150:     fprintf(stderr, "%d B", (int)value);
1151:   } else if (value < 1048576) {
1152:     fprintf(stderr, "%0.3f KiB", (double)value / 1024.0);
1153:   } else if (value < 1073741824) {
1154:     fprintf(stderr, "%0.3f MiB", (double)value / 1048576.0);
1155:   } else {
1156:     fprintf(stderr, "%0.3f GiB", (double)value / 1073741824.0);
1157:   }
1158: }
1159: 
1160: static void PrintFileProcessingProgress(Context* context) {
1161:   fprintf(stderr, "[%s]: ", PrintablePath(context->current_input_path));
1162:   PrintBytes(context->total_in);
1163:   fprintf(stderr, " -> ");
1164:   PrintBytes(context->total_out);
1165:   fprintf(stderr, " in %1.2f sec", (double)(context->end_time - context->start_time) / CLOCKS_PER_SEC);
1166: }
