1168: static const char* PrettyDecoderErrorString(BrotliDecoderErrorCode code) {
1169:   /* "_ERROR_domain_" is in only added in newer versions. If CLI is linked
1170:      against older shared library, return error string as is; result might be
1171:      a bit confusing, e.g. "RESERVED" instead of "FORMAT_RESERVED" */
1172:   const char* prefix = "_ERROR_";
1173:   size_t prefix_len = strlen(prefix);
1174:   const char* error_str = BrotliDecoderErrorString(code);
1175:   size_t error_len = strlen(error_str);
1176:   if (error_len > prefix_len) {
1177:     if (strncmp(error_str, prefix, prefix_len) == 0) {
1178:       error_str += prefix_len;
1179:     }
1180:   }
1181:   return error_str;
1182: }
