1184: static void OnMetadataStart(void* opaque, size_t size) {
1185:   Context* context = (Context*) opaque;
1186:   if (context->comment_state == COMMENT_INIT) {
1187:     if (context->comment_len != size) {
1188:       context->comment_state = COMMENT_BAD;
1189:       return;
1190:     }
1191:     context->comment_pos = 0;
1192:     context->comment_state = COMMENT_READ;
1193:   }
1194: }
1195: 
1196: static void OnMetadataChunk(void* opaque, const uint8_t* data, size_t size) {
1197:   Context* context = (Context*) opaque;
1198:   if (context->comment_state == COMMENT_READ) {
1199:     size_t i;
1200:     for (i = 0; i < size; ++i) {
1201:       if (context->comment_pos >= context->comment_len) {
1202:         context->comment_state = COMMENT_BAD;
1203:         return;
1204:       }
1205:       if (context->comment[context->comment_pos++] != data[i]) {
1206:         context->comment_state = COMMENT_BAD;
1207:         return;
1208:       }
1209:     }
1210:     if (context->comment_pos == context->comment_len) {
1211:       context->comment_state = COMMENT_OK;
1212:     }
1213:   }
1214: }
