1216: static BROTLI_BOOL InitDecoder(Context* context) {
1217:   context->decoder = BrotliDecoderCreateInstance(NULL, NULL, NULL);
1218:   if (!context->decoder) {
1219:     fprintf(stderr, "out of memory\n");
1220:     return BROTLI_FALSE;
1221:   }
1222:   /* This allows decoding "large-window" streams. Though it creates
1223:       fragmentation (new builds decode streams that old builds don't),
1224:       it is better from used experience perspective. */
1225:   BrotliDecoderSetParameter(
1226:       context->decoder, BROTLI_DECODER_PARAM_LARGE_WINDOW, 1u);
1227:   if (context->dictionary) {
1228:     BrotliDecoderAttachDictionary(context->decoder,
1229:         BROTLI_SHARED_DICTIONARY_RAW, context->dictionary_size,
1230:         context->dictionary);
1231:   }
1232:   return BROTLI_TRUE;
1233: }
1234: 
1235: static BROTLI_BOOL DecompressFile(Context* context) {
1236:   BrotliDecoderState* s = context->decoder;
1237:   BrotliDecoderResult result = BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT;
1238:   if (context->comment_len) {
1239:     context->comment_state = COMMENT_INIT;
1240:     BrotliDecoderSetMetadataCallbacks(s, &OnMetadataStart, &OnMetadataChunk,
1241:         (void*)context);
1242:   } else {
1243:     context->comment_state = COMMENT_OK;
1244:   }
1245: 
1246:   InitializeBuffers(context);
1247:   for (;;) {
1248:     /* Early check */
1249:     if (context->comment_state == COMMENT_BAD) {
1250:       fprintf(stderr, "corrupt input [%s]\n",
1251:               PrintablePath(context->current_input_path));
1252:       if (context->verbosity > 0) {
1253:         fprintf(stderr, "reason: comment mismatch\n");
1254:       }
1255:       return BROTLI_FALSE;
1256:     }
1257:     if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT) {
1258:       if (!HasMoreInput(context)) {
1259:         fprintf(stderr, "corrupt input [%s]\n",
1260:                 PrintablePath(context->current_input_path));
1261:         if (context->verbosity > 0) {
1262:           fprintf(stderr, "reason: truncated input\n");
1263:         }
1264:         return BROTLI_FALSE;
1265:       }
1266:       if (!ProvideInput(context)) return BROTLI_FALSE;
1267:     } else if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT) {
1268:       if (!ProvideOutput(context)) return BROTLI_FALSE;
1269:     } else if (result == BROTLI_DECODER_RESULT_SUCCESS) {
1270:       if (!FlushOutput(context)) return BROTLI_FALSE;
1271:       BROTLI_BOOL has_more_input = (context->available_in != 0);
1272:       int extra_char = EOF;
1273:       if (!has_more_input) {
1274:         extra_char = fgetc(context->fin);
1275:         if (extra_char != EOF) {
1276:           has_more_input = BROTLI_TRUE;
1277:           context->input[0] = (uint8_t)extra_char;
1278:           context->next_in = context->input;
1279:           context->available_in = 1;
1280:         }
1281:       }
1282:       if (has_more_input) {
1283:         if (context->allow_concatenated) {
1284:           if (context->verbosity > 0) {
1285:             fprintf(stderr, "extra input\n");
1286:           }
1287:           if (!ProvideOutput(context)) return BROTLI_FALSE;
1288:           BrotliDecoderDestroyInstance(context->decoder);
1289:           context->decoder = NULL;
1290:           if (!InitDecoder(context)) return BROTLI_FALSE;
1291:           s = context->decoder;
1292:         } else {
1293:           fprintf(stderr, "corrupt input [%s]\n",
1294:                   PrintablePath(context->current_input_path));
1295:           if (context->verbosity > 0) {
1296:             fprintf(stderr, "reason: extra input\n");
1297:           }
1298:           return BROTLI_FALSE;
1299:         }
1300:       } else {
1301:         if (context->verbosity > 0) {
1302:           context->end_time = clock();
1303:           fprintf(stderr, "Decompressed ");
1304:           PrintFileProcessingProgress(context);
1305:           fprintf(stderr, "\n");
1306:         }
1307:         /* Final check */
1308:         if (context->comment_state != COMMENT_OK) {
1309:           fprintf(stderr, "corrupt input [%s]\n",
1310:                   PrintablePath(context->current_input_path));
1311:           if (context->verbosity > 0) {
1312:             fprintf(stderr, "reason: comment mismatch\n");
1313:           }
1314:           return BROTLI_FALSE;
1315:         }
1316:         return BROTLI_TRUE;
1317:       }
1318:     } else {  /* result == BROTLI_DECODER_RESULT_ERROR */
1319:       fprintf(stderr, "corrupt input [%s]\n",
1320:               PrintablePath(context->current_input_path));
1321:       if (context->verbosity > 0) {
1322:         BrotliDecoderErrorCode error = BrotliDecoderGetErrorCode(s);
1323:         const char* error_str = PrettyDecoderErrorString(error);
1324:         fprintf(stderr, "reason: %s (%d)\n", error_str, error);
1325:       }
1326:       return BROTLI_FALSE;
1327:     }
1328: 
1329:     result = BrotliDecoderDecompressStream(s, &context->available_in,
1330:         &context->next_in, &context->available_out, &context->next_out, 0);
1331:   }
1332: }
1333: 
1334: static BROTLI_BOOL DecompressFiles(Context* context) {
1335:   while (NextFile(context)) {
1336:     BROTLI_BOOL is_ok = BROTLI_TRUE;
1337:     BROTLI_BOOL rm_input = BROTLI_FALSE;
1338:     BROTLI_BOOL rm_output = BROTLI_TRUE;
1339:     if (!InitDecoder(context)) return BROTLI_FALSE;
1340:     is_ok = OpenFiles(context);
1341:     if (is_ok && !context->current_input_path &&
1342:         !context->force_overwrite && isatty(STDIN_FILENO)) {
1343:       fprintf(stderr, "Use -h help. Use -f to force input from a terminal.\n");
1344:       is_ok = BROTLI_FALSE;
1345:     }
1346:     if (is_ok) is_ok = DecompressFile(context);
1347:     if (context->decoder) BrotliDecoderDestroyInstance(context->decoder);
1348:     context->decoder = NULL;
1349:     rm_output = !is_ok;
1350:     rm_input = !rm_output && context->junk_source;
1351:     if (!CloseFiles(context, rm_input, rm_output)) is_ok = BROTLI_FALSE;
1352:     if (!is_ok) return BROTLI_FALSE;
1353:   }
1354:   return BROTLI_TRUE;
1355: }
1356: 
1357: static BROTLI_BOOL CompressFile(Context* context, BrotliEncoderState* s) {
1358:   BROTLI_BOOL is_eof = BROTLI_FALSE;
1359:   BROTLI_BOOL prologue = !!context->comment_len;
1360:   InitializeBuffers(context);
1361:   for (;;) {
1362:     if (context->available_in == 0 && !is_eof) {
1363:       if (!ProvideInput(context)) return BROTLI_FALSE;
1364:       is_eof = !HasMoreInput(context);
1365:     }
1366: 
1367:     if (prologue) {
1368:       prologue = BROTLI_FALSE;
1369:       const uint8_t* next_meta = context->comment;
1370:       size_t available_meta = context->comment_len;
1371:       if (!BrotliEncoderCompressStream(s,
1372:           BROTLI_OPERATION_EMIT_METADATA,
1373:           &available_meta, &next_meta,
1374:           &context->available_out, &context->next_out, NULL)) {
1375:         /* Should detect OOM? */
1376:         fprintf(stderr, "failed to emit metadata [%s]\n",
1377:                 PrintablePath(context->current_input_path));
1378:         return BROTLI_FALSE;
1379:       }
1380:       if (available_meta != 0) {
1381:         fprintf(stderr, "failed to emit metadata [%s]\n",
1382:                 PrintablePath(context->current_input_path));
1383:         return BROTLI_FALSE;
1384:       }
1385:     } else {
1386:       if (!BrotliEncoderCompressStream(s,
1387:           is_eof ? BROTLI_OPERATION_FINISH : BROTLI_OPERATION_PROCESS,
1388:           &context->available_in, &context->next_in,
1389:           &context->available_out, &context->next_out, NULL)) {
1390:         /* Should detect OOM? */
1391:         fprintf(stderr, "failed to compress data [%s]\n",
1392:                 PrintablePath(context->current_input_path));
1393:         return BROTLI_FALSE;
1394:       }
1395:     }
1396: 
1397:     if (context->available_out == 0) {
1398:       if (!ProvideOutput(context)) return BROTLI_FALSE;
1399:     }
1400: 
1401:     if (BrotliEncoderIsFinished(s)) {
1402:       if (!FlushOutput(context)) return BROTLI_FALSE;
1403:       if (context->verbosity > 0) {
1404:         context->end_time = clock();
1405:         fprintf(stderr, "Compressed ");
1406:         PrintFileProcessingProgress(context);
1407:         fprintf(stderr, "\n");
1408:       }
1409:       return BROTLI_TRUE;
1410:     }
1411:   }
1412: }
1413: 
1414: static BROTLI_BOOL CompressFiles(Context* context) {
1415:   while (NextFile(context)) {
1416:     BROTLI_BOOL is_ok = BROTLI_TRUE;
1417:     BROTLI_BOOL rm_input = BROTLI_FALSE;
1418:     BROTLI_BOOL rm_output = BROTLI_TRUE;
1419:     BrotliEncoderState* s = BrotliEncoderCreateInstance(NULL, NULL, NULL);
1420:     if (!s) {
1421:       fprintf(stderr, "out of memory\n");
1422:       return BROTLI_FALSE;
1423:     }
1424:     BrotliEncoderSetParameter(s,
1425:         BROTLI_PARAM_QUALITY, (uint32_t)context->quality);
1426:     if (context->lgwin > 0) {
1427:       /* Specified by user. */
1428:       /* Do not enable "large-window" extension, if not required. */
1429:       if (context->lgwin > BROTLI_MAX_WINDOW_BITS) {
1430:         BrotliEncoderSetParameter(s, BROTLI_PARAM_LARGE_WINDOW, 1u);
1431:       }
1432:       BrotliEncoderSetParameter(s,
1433:           BROTLI_PARAM_LGWIN, (uint32_t)context->lgwin);
1434:     } else {
1435:       /* 0, or not specified by user; could be chosen by compressor. */
1436:       uint32_t lgwin = DEFAULT_LGWIN;
1437:       /* Use file size to limit lgwin. */
